import torch.nn as nn

def attach_exploding_grad_detector(model, threshold=10.0):
    handles = []

    def make_hook(name):
        def hook(module, grad_input, grad_output):
            for g in grad_output:
                if g is not None:
                    norm = g.norm().item()
                    if norm > threshold:
                        print(f"[WARNING] Exploding gradient in '{name}': norm={norm:.2f}")
        return hook

    for name, module in model.named_modules():
        if isinstance(module, nn.Linear):
            handles.append(module.register_full_backward_hook(make_hook(name)))
    return handles

model = nn.Sequential(nn.Linear(10, 10), nn.ReLU(), nn.Linear(10, 1))
handles = attach_exploding_grad_detector(model, threshold=0.01)
x = torch.randn(4, 10)
out = model(x)
out.sum().backward()
for h in handles:
