from torch.utils.data import Dataset, DataLoader
from torchvision import transforms

class LargeImageDataset(Dataset):
    def __init__(self, image_dir):
        self.image_dir = image_dir
        self.filenames = os.listdir(image_dir)
        self.transform = transforms.Compose([
            transforms.RandomCrop(224, pad_if_needed=True),
            transforms.RandomHorizontalFlip(),
            transforms.ToTensor(),
            transforms.Normalize(mean=[0.485, 0.456, 0.406], std=[0.229, 0.224, 0.225]),
        ])

    def __len__(self):
        return len(self.filenames)

    def __getitem__(self, idx):
        path = os.path.join(self.image_dir, self.filenames[idx])
        img = Image.open(path).convert('RGB')
        return self.transform(img)

dataset = LargeImageDataset('/path/to/images')
loader = DataLoader(dataset, batch_size=32, shuffle=True, num_workers=4, pin_memory=True)

import torch

def move_model_to_device(model, device_str='cuda'):
    if device_str == 'cuda' and not torch.cuda.is_available():
        print("CUDA not available, falling back to CPU")
        device_str = 'cpu'
    device = torch.device(device_str)
    model = model.to(device)

    for name, p in model.named_parameters():
        assert p.device == device, f"Parameter {name} not on {device}"
    for name, b in model.named_buffers():
        assert b.device == device, f"Buffer {name} not on {device}"

    print(f"All parameters and buffers verified on {device}")
    return model

