from torch.utils.data import IterableDataset, DataLoader

def remote_data_generator(n_samples=1000):
    for i in range(n_samples):
        # simulate fetching a raw sample from a remote source
        yield torch.tensor([i], dtype=torch.float32)

class StreamingDataset(IterableDataset):
    def __init__(self, n_samples):
        self.n_samples = n_samples

    def __iter__(self):
        for raw in remote_data_generator(self.n_samples):
            transformed = raw * 2.0 + 1.0  # example transform applied on the fly
            yield transformed

